//! Offline agent configuration compilation, planning and drift checks.
pub mod config;
pub mod emit;
pub mod import;
pub mod io;
mod merge;
pub mod org;
pub mod sources;
use cedr_core::finding::{Finding, Report, Rule, Severity};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{collections::BTreeMap, path::Path};
pub type Result<T> = std::result::Result<T, String>;
pub const HEADER: &str =
    "<!-- Generated by cedr sync from .cedr/. Edit those files and run cedr sync. -->";

/// Puts the generated-file header where each agent still reads the file: first, or, when the file opens with YAML
/// front matter (Cursor, Claude Code, Copilot and Antigravity rules), on the line after it, since those agents only
/// recognise front matter on the first line.
pub fn with_header(text: &str) -> String {
    let text = text.trim_end();
    if let Some(rest) = text.strip_prefix("---\n")
        && let Some(end) = rest.find("\n---\n")
    {
        let (front, body) = rest.split_at(end + 5);
        return format!("---\n{front}{HEADER}\n{}\n", body.trim_start_matches('\n'));
    }
    format!("{HEADER}\n{text}\n")
}

/// The text without the generated-file header, wherever `with_header` put it.
pub fn strip_header(text: &str) -> String {
    text.replacen(&format!("{HEADER}\n"), "", 1)
        .replacen(HEADER, "", 1)
}

/// Whether a file carries the generated-file header, first or right after its front matter.
pub fn is_generated(bytes: &[u8]) -> bool {
    let Ok(text) = std::str::from_utf8(bytes) else {
        return false;
    };
    if text.starts_with(HEADER) {
        return true;
    }
    text.strip_prefix("---\n")
        .and_then(|rest| rest.split_once("\n---\n"))
        .is_some_and(|(_, body)| body.starts_with(HEADER))
}
pub fn hash(bytes: &[u8]) -> String {
    format!(
        "sha256-{}",
        Sha256::digest(bytes)
            .iter()
            .map(|b| format!("{b:02x}"))
            .collect::<String>()
    )
}
#[derive(Clone, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Entry {
    pub target: String,
    pub hash: String,
    #[serde(default)]
    pub keys: Vec<String>,
}
#[derive(Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Lock {
    pub version: u32,
    pub files: BTreeMap<String, Entry>,
}
#[derive(Serialize)]
pub struct File {
    pub path: String,
    pub target: String,
    pub state: String,
    pub diff: String,
    #[serde(skip)]
    pub bytes: Option<Vec<u8>>,
}
pub struct Plan {
    pub files: Vec<File>,
    pub notes: Vec<String>,
    pub lock: Lock,
    pub report: Report,
    pub config: config::Config,
    pub policy: Option<serde_json::Value>,
    pub counts: serde_json::Value,
}
pub fn load_config(root: &Path) -> Result<config::Config> {
    let bytes =
        io::read(root, ".cedr/sync.toml")?.ok_or(".cedr/sync.toml: missing; run cedr sync init")?;
    config::Config::parse(
        std::str::from_utf8(&bytes).map_err(|_| ".cedr/sync.toml: invalid UTF-8")?,
    )
}
fn read_lock(root: &Path) -> Result<Lock> {
    let lock: Lock = io::read(root, ".cedr/sync.lock")?
        .map(|b| {
            serde_json::from_slice(&b).map_err(|_| ".cedr/sync.lock: invalid lock".to_string())
        })
        .transpose()?
        .unwrap_or_default();
    for path in lock.files.keys() {
        io::path(root, path)?;
    }
    Ok(lock)
}
pub fn plan(root: &Path) -> Result<Plan> {
    let root = std::fs::canonicalize(root).map_err(|_| "sync: cannot resolve root")?;
    io::path(&root, ".cedr/sync.toml")?;
    let mut config = load_config(&root)?;
    let rules = sources::rules(&root, &config.targets)?;
    let mut skills = sources::skills(&root, ".cedr/skills")?;
    let policy = org::load(&root)?;
    let mut findings = vec![];
    if let Some(v) = &policy {
        findings.extend(org::apply(&mut config, &mut skills, v)?);
    }
    let counts = serde_json::json!({"rules":rules.len(),"skills":skills.len(),"servers":config.mcp.len(),"allow":config.permissions.allow.len(),"deny":config.permissions.deny.len(),"hooks":config.hooks.len()});
    let (mut outputs, notes) = emit::emit(
        &config,
        &rules,
        &skills,
        policy
            .as_ref()
            .and_then(|p| p["instructions"].as_str())
            .unwrap_or(""),
    );
    let old = read_lock(&root)?;
    let mut files = vec![];
    let mut lock = Lock {
        version: 1,
        ..Default::default()
    };
    let paths: std::collections::BTreeSet<_> =
        outputs.keys().chain(old.files.keys()).cloned().collect();
    for path in paths {
        let current = io::read(&root, &path)?;
        let previous = old.files.get(&path);
        let output = outputs.remove(&path);
        let keys = output
            .as_ref()
            .map(|o| o.keys.as_slice())
            .unwrap_or_default();
        let old_keys = previous.map(|e| e.keys.as_slice()).unwrap_or_default();
        let merged = !keys.is_empty() || !old_keys.is_empty();
        let mut bytes = if merged {
            merge::merge(
                &path,
                current.as_deref(),
                old_keys,
                output.as_ref().map(|o| o.bytes.as_slice()),
                keys,
            )?
        } else {
            output.as_ref().map(|o| o.bytes.clone())
        };
        if merged
            && old_keys == keys
            && let (Some(current), Some(desired)) = (&current, &bytes)
            && merge::owned(&path, current, keys)? == merge::owned(&path, desired, keys)?
        {
            bytes = Some(current.clone());
        }
        let mut state = "ok";
        if output.is_some() && current.is_none() {
            state = "missing";
            findings.push(Finding::new(
                Rule::Cs003,
                Severity::Error,
                &path,
                None,
                "generated file is missing",
            ));
        } else if let (Some(entry), Some(b)) = (previous, current.as_ref())
            && hash(&merge::owned(&path, b, old_keys)?) != entry.hash
        {
            state = "edited";
            findings.push(Finding::new(
                Rule::Cs002,
                Severity::Error,
                &path,
                None,
                "generated file was edited by hand",
            ));
        }
        if current != bytes && state == "ok" {
            state = "drift";
            findings.push(Finding::new(
                Rule::Cs001,
                Severity::Error,
                &path,
                None,
                "generated file differs from sources",
            ));
        }
        if let Some(output) = &output {
            let b = bytes.as_ref().ok_or("sync: missing output")?;
            lock.files.insert(
                path.clone(),
                Entry {
                    target: output.target.clone(),
                    hash: hash(&merge::owned(&path, b, keys)?),
                    keys: keys.to_vec(),
                },
            );
        }
        if policy.as_ref().is_some_and(|v| {
            v["skills"].as_array().is_some_and(|a| {
                a.iter().any(|s| {
                    s["name"]
                        .as_str()
                        .is_some_and(|n| path.contains(&format!("/skills/{n}/")))
                })
            })
        }) && state != "ok"
        {
            findings.push(Finding::new(
                Rule::Cs104,
                Severity::Error,
                &path,
                None,
                "required organization skill is missing or changed",
            ));
        }
        let diff = if current != bytes
            && current
                .as_ref()
                .is_none_or(|b| std::str::from_utf8(b).is_err())
            && bytes
                .as_ref()
                .is_none_or(|b| std::str::from_utf8(b).is_err())
        {
            format!("Binary files a/{path} and b/{path} differ\n")
        } else if current == bytes {
            String::new()
        } else {
            similar::TextDiff::from_lines(
                &display_bytes(&path, current.as_deref().unwrap_or_default()),
                &display_bytes(&path, bytes.as_deref().unwrap_or_default()),
            )
            .unified_diff()
            .header(&format!("a/{path}"), &format!("b/{path}"))
            .to_string()
        };
        let target = lock
            .files
            .get(&path)
            .or(previous)
            .map(|e| e.target.clone())
            .unwrap_or_default();
        files.push(File {
            path,
            target,
            state: state.into(),
            diff,
            bytes,
        });
    }
    Ok(Plan {
        files,
        notes,
        lock,
        report: Report::new(findings),
        config,
        policy,
        counts,
    })
}
pub fn check(root: &Path) -> Report {
    match plan(root) {
        Ok(p) => p.report,
        Err(e) => Report::new(vec![Finding::new(
            Rule::Cs004,
            Severity::Error,
            ".cedr/sync.toml",
            None,
            e,
        )]),
    }
}
pub fn apply(root: &Path, p: &Plan, force: bool) -> Result<bool> {
    let previous = read_lock(root)?;
    for f in &p.files {
        if !force && f.state == "edited" {
            return Ok(false);
        }
        if !force
            && (f.path.ends_with(".md") || f.path.ends_with(".mdc"))
            && !p
                .lock
                .files
                .get(&f.path)
                .is_some_and(|e| !e.keys.is_empty())
            && io::read(root, &f.path)?.is_some_and(|b| !is_generated(&b))
            && !previous.files.contains_key(&f.path)
            && !imported(root, &f.path, &p.config.targets)?
        {
            return Ok(false);
        }
    }
    // Validate every destination before the first mutation.
    for f in &p.files {
        io::path(root, &f.path)?;
    }
    for f in &p.files {
        if io::read(root, &f.path)? != f.bytes {
            match &f.bytes {
                Some(b) => io::write(root, &f.path, b)?,
                None => std::fs::remove_file(io::path(root, &f.path)?)
                    .map_err(|_| format!("sync: cannot remove {}", f.path))?,
            }
        }
    }
    io::write(
        root,
        ".cedr/sync.lock",
        format!("{}\n", serde_json::to_string_pretty(&p.lock).expect("lock")).as_bytes(),
    )?;
    Ok(true)
}

fn imported(root: &Path, path: &str, targets: &[String]) -> Result<bool> {
    let target = match path {
        "AGENTS.md" => "agents",
        "CLAUDE.md" => "claude",
        "GEMINI.md" => "gemini",
        ".github/copilot-instructions.md" => "copilot",
        _ => return Ok(false),
    };
    let current = io::read(root, path)?.unwrap_or_default();
    let text = std::str::from_utf8(&current)
        .map_err(|_| "sync: invalid Markdown UTF-8")?
        .replace("\r\n", "\n");
    Ok(sources::rules(root, targets)?.iter().any(|r| {
        r.body.trim() == text.trim()
            && if target == "agents" {
                r.meta.agents.is_none()
            } else {
                r.meta
                    .agents
                    .as_ref()
                    .is_some_and(|a| a.iter().any(|t| t == target))
            }
    }))
}

/// Native files imported before their first compile may still contain literal credentials.
/// Diff rendering must not reveal those values while showing their replacement references.
fn display_bytes(path: &str, bytes: &[u8]) -> String {
    let mut text = String::from_utf8_lossy(bytes).into_owned();
    if !path.ends_with(".json") && !path.ends_with(".toml") {
        return redact_urls(&text);
    }
    fn collect(value: &serde_json::Value, private: bool, values: &mut Vec<String>) {
        match value {
            serde_json::Value::Object(map) => {
                for (key, v) in map {
                    collect(
                        v,
                        private
                            || ["env", "environment", "headers", "http_headers"]
                                .contains(&key.as_str()),
                        values,
                    )
                }
            }
            serde_json::Value::Array(items) => {
                for v in items {
                    collect(v, private, values)
                }
            }
            serde_json::Value::String(s)
                if private
                    && !s.is_empty()
                    && (config::secret(s) || (!s.contains("${") && !s.contains("{env:"))) =>
            {
                values.push(s.clone())
            }
            _ => (),
        }
    }
    if let Ok(value) = merge::value(path, bytes) {
        let mut values = vec![];
        collect(&value, false, &mut values);
        values.sort_by_key(|s| std::cmp::Reverse(s.len()));
        values.dedup();
        for value in values {
            text = text.replace(
                &serde_json::to_string(&value).expect("string"),
                "\"[redacted]\"",
            );
            if path.ends_with(".toml") {
                text = text.replace(&format!("'{value}'"), "'[redacted]'");
            }
        }
    }
    redact_urls(&text)
}
fn redact_urls(text: &str) -> String {
    static URLS: std::sync::LazyLock<regex::Regex> =
        std::sync::LazyLock::new(|| regex::Regex::new(r#"https?://[^\s"'<>]+"#).expect("regex"));
    URLS.replace_all(text, |c: &regex::Captures<'_>| {
        cedr_core::source::redact_url(&c[0])
    })
    .into_owned()
}

#[cfg(test)]
mod header_tests {
    use super::*;

    #[test]
    fn the_header_follows_front_matter_so_agents_still_read_it() {
        let rule = with_header("---\nglobs: \"src/**\"\n---\nValidate input.\n");
        assert_eq!(
            rule,
            format!("---\nglobs: \"src/**\"\n---\n{HEADER}\nValidate input.\n")
        );
        assert!(is_generated(rule.as_bytes()));
        assert_eq!(with_header("Plain."), format!("{HEADER}\nPlain.\n"));
        assert!(is_generated(with_header("Plain.").as_bytes()));
        assert!(!is_generated(b"---\na: b\n---\nHand written.\n"));
        assert_eq!(
            strip_header(&rule),
            "---\nglobs: \"src/**\"\n---\nValidate input.\n"
        );
    }
}
